import React, { useState } from 'react';

// Create the LegacyCodeSimulator component here
const LegacyCodeSimulator = () => {
  // Initialize state for legacy system status here
  const [legacyStatus, setLegacyStatus] = useState('operational');
  // Initialize state for technical debt level here
  const [technicalDebt, setTechnicalDebt] = useState(0);
  // Initialize state for rewrite progress here
  const [rewriteProgress, setRewriteProgress] = useState(0);

  // Create the accumulateDebt function here
  const accumulateDebt = () => {
    setTechnicalDebt(prev => prev + 10);
    if (technicalDebt >= 50) {
      setLegacyStatus('critical');
    }
  };

  // Create the startRewrite function here
  const startRewrite = () => {
    if (legacyStatus === 'critical' && rewriteProgress === 0) {
      setRewriteProgress(5);
      setLegacyStatus('rewriting');
    }
  };

  // Create the makeProgress function here
  const makeProgress = () => {
    if (legacyStatus === 'rewriting' && rewriteProgress < 100) {
      setRewriteProgress(prev => prev + 10);
      if (rewriteProgress >= 100) {
        setLegacyStatus('modernized');
      }
    }
  };

  return (
    <div>
      <p>Current System Status: {legacyStatus}</p>
      <p>Technical Debt: {technicalDebt}</p>
      <p>Rewrite Progress: {rewriteProgress}%</p>
      {/* Add your three control buttons here */}
    </div>
  );
};
